CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS session (id text PRIMARY KEY, "expiresAt" timestamp NOT NULL, token text NOT NULL UNIQUE, "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text, "userId" text NOT NULL);
CREATE TABLE IF NOT EXISTS account (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamp, "refreshTokenExpiresAt" timestamp, scope text, password text, "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamp NOT NULL, "createdAt" timestamp DEFAULT now(), "updatedAt" timestamp DEFAULT now());
CREATE TABLE IF NOT EXISTS project (id text PRIMARY KEY, "userId" text NOT NULL, title text NOT NULL, genre text NOT NULL, "visualStyle" text NOT NULL DEFAULT 'Atmospheric', "styleVersion" integer NOT NULL DEFAULT 1, logline text, status text NOT NULL DEFAULT 'Draft', "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS scene (id text PRIMARY KEY, "projectId" text NOT NULL, "userId" text NOT NULL, position integer NOT NULL, title text NOT NULL, description text NOT NULL, "shotPrompt" text, narration text, metadata jsonb DEFAULT '{}', "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS generation_job (id text PRIMARY KEY, "projectId" text NOT NULL, "userId" text NOT NULL, type text NOT NULL, status text NOT NULL DEFAULT 'queued', progress integer NOT NULL DEFAULT 0, message text, payload jsonb DEFAULT '{}', error text, attempts integer NOT NULL DEFAULT 0, "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asset (id text PRIMARY KEY, "projectId" text NOT NULL, "userId" text NOT NULL, "sceneId" text, type text NOT NULL, pathname text NOT NULL, "mimeType" text NOT NULL, size integer, metadata jsonb DEFAULT '{}', "createdAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS movie_export (id text PRIMARY KEY, "projectId" text NOT NULL, "userId" text NOT NULL, status text NOT NULL DEFAULT 'queued', progress integer NOT NULL DEFAULT 0, "outputAssetId" text, error text, "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS job_event (id text PRIMARY KEY, "jobId" text NOT NULL, "userId" text NOT NULL, status text NOT NULL, progress integer NOT NULL, message text, "createdAt" timestamp NOT NULL DEFAULT now());
ALTER TABLE "project" ADD COLUMN IF NOT EXISTS "visualStyle" text NOT NULL DEFAULT 'Atmospheric';
ALTER TABLE "project" ADD COLUMN IF NOT EXISTS "styleVersion" integer NOT NULL DEFAULT 1;
ALTER TABLE "project" ADD COLUMN IF NOT EXISTS logline text;
